  ('quant', 'LCM & HCF', 1, 'What is the HCF of 54 and 126?', array['18', '9', '3', '6'], 0, '54 = 18 × 3 and 126 = 18 × 7, and 3 and 7 share no factor. So the HCF is 18.', 30, 'basic_hcf_two'),
