  ('quant', 'Ages', 1, 'The sum of the ages of a father and son is 52 years. The father is 34 years older. How old is the father?', array['26 years', '9 years', '37 years', '43 years'], 3, 'Son = (sum − difference) ÷ 2 = (52 − 34) ÷ 2 = 9. Father = 9 + 34 = 43.', 30, 'basic_ages_sum_diff'),
